    PyObject *wo, *co;
    if (!PyArg_ParseTuple(args, "OO", &wo, &co)) return NULL;
    PyArrayObject *w = (PyArrayObject*)PyArray_FROM_OTF(wo, NPY_DOUBLE, NPY_ARRAY_C_CONTIGUOUS|NPY_ARRAY_ALIGNED);
    PyArrayObject *c = (PyArrayObject*)PyArray_FROM_OTF(co, NPY_DOUBLE, NPY_ARRAY_C_CONTIGUOUS|NPY_ARRAY_ALIGNED);
    if (!w || !c) { Py_XDECREF(w); Py_XDECREF(c); return NULL; }
    npy_intp n = PyArray_DIM(w,0), i, j;
    const double *wd = PyArray_DATA(w), *cd = PyArray_DATA(c);
    double s = 0.0;
    for (i = 0; i < n; i++) { const double *row = cd + i*n; double rs = 0.0;
        for (j = 0; j < n; j++) rs += row[j]*wd[j];
        s += wd[i]*rs; }
    Py_DECREF(w); Py_DECREF(c);
    return PyFloat_FromDouble(sqrt(s));
