/*
 * High-performance portfolio calculations using C extension
 *
 * Uses the NumPy C API for zero-copy access to contiguous float64 arrays.
 * Nested Python sequences (the common list-of-lists covariance matrix) are
 * read directly to avoid building a large temporary NumPy array.
 * The summation order matches the pure Python baseline exactly so that
 * results agree to within floating-point round-off.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/* Convert an arbitrary object to a C-contiguous, aligned float64 array. */
static PyArrayObject* as_float64_array(PyObject *obj) {
    return (PyArrayObject*)PyArray_FROM_OTF(
        obj, NPY_DOUBLE, NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
}

/*
 * Compute x^T * S * x reading S directly from a nested Python sequence.
 *
 * Returns 1 on success (result stored in *out), 0 if the object is not a
 * sequence of equal-length float list/tuple rows (caller should fall back
 * to the generic NumPy conversion), and -1 on a hard error.
 */
static int risk_squared_from_sequence(PyObject *cov_obj, const double *w,
                                      npy_intp n, double *out) {
    PyObject *outer, **rows;
    npy_intp i, j;
    double risk_squared = 0.0;
    int status = 1;

    outer = PySequence_Fast(cov_obj, "cov_matrix must be a sequence");
    if (outer == NULL) {
        PyErr_Clear();
        return 0;
    }

    if (PySequence_Fast_GET_SIZE(outer) != n) {
        Py_DECREF(outer);
        return 0;
    }
    rows = PySequence_Fast_ITEMS(outer);

    for (i = 0; i < n; i++) {
        PyObject *row_obj = rows[i];
        Py_ssize_t row_len;
        double row_sum = 0.0;

        if (!PyList_CheckExact(row_obj) && !PyTuple_CheckExact(row_obj)) {
            status = 0;
            break;
        }
        row_len = PySequence_Fast_GET_SIZE(row_obj);
        if (row_len != n) {
            status = 0;
            break;
        }

        for (j = 0; j < n; j++) {
            PyObject *elem = PySequence_Fast_GET_ITEM(row_obj, j);
            if (!PyFloat_CheckExact(elem)) {
                status = 0;
                break;
            }
            row_sum += PyFloat_AS_DOUBLE(elem) * w[j];
        }
        if (status == 0)
            break;

        risk_squared += w[i] * row_sum;
    }

    Py_DECREF(outer);
    if (status == 1)
        *out = risk_squared;
    return status;
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;
    PyArrayObject *weights_array, *cov_array;
    const double *w, *cov;
    npy_intp n, i, j;
    double risk_squared = 0.0;

    /* Parse NumPy arrays (sequences are also accepted) */
    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    weights_array = as_float64_array(weights_obj);
    if (weights_array == NULL)
        return NULL;

    if (PyArray_NDIM(weights_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights must be 1-D");
        Py_DECREF(weights_array);
        return NULL;
    }

    n = PyArray_DIM(weights_array, 0);
    w = (const double*)PyArray_DATA(weights_array);

    /* Fast path: read a nested list/tuple covariance matrix in place. */
    if (!PyArray_Check(cov_obj)) {
        int status = risk_squared_from_sequence(cov_obj, w, n, &risk_squared);
        if (status == 1) {
            Py_DECREF(weights_array);
            return PyFloat_FromDouble(sqrt(risk_squared));
        }
        if (status < 0) {
            Py_DECREF(weights_array);
            return NULL;
        }
        /* status == 0: fall through to generic conversion below */
    }

    cov_array = as_float64_array(cov_obj);
    if (cov_array == NULL) {
        Py_DECREF(weights_array);
        return NULL;
    }

    if (PyArray_NDIM(cov_array) != 2) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix must be 2-D");
        Py_DECREF(weights_array);
        Py_DECREF(cov_array);
        return NULL;
    }

    if (PyArray_DIM(cov_array, 0) != n || PyArray_DIM(cov_array, 1) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix must be square with size len(weights)");
        Py_DECREF(weights_array);
        Py_DECREF(cov_array);
        return NULL;
    }

    cov = (const double*)PyArray_DATA(cov_array);

    /* risk = sqrt(x^T * S * x), accumulated in the same order as the
     * Python baseline: first S * x row by row, then x^T * (S * x). */
    for (i = 0; i < n; i++) {
        const double *row = cov + i * n;
        double row_sum = 0.0;
        for (j = 0; j < n; j++) {
            row_sum += row[j] * w[j];
        }
        risk_squared += w[i] * row_sum;
    }

    Py_DECREF(weights_array);
    Py_DECREF(cov_array);

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;
    PyArrayObject *weights_array, *returns_array;
    const double *w, *r;
    npy_intp n, i;
    double total_return = 0.0;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    weights_array = as_float64_array(weights_obj);
    if (weights_array == NULL)
        return NULL;

    returns_array = as_float64_array(returns_obj);
    if (returns_array == NULL) {
        Py_DECREF(weights_array);
        return NULL;
    }

    if (PyArray_NDIM(weights_array) != 1 || PyArray_NDIM(returns_array) != 1) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must be 1-D");
        Py_DECREF(weights_array);
        Py_DECREF(returns_array);
        return NULL;
    }

    n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(returns_array, 0) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must have the same length");
        Py_DECREF(weights_array);
        Py_DECREF(returns_array);
        return NULL;
    }

    w = (const double*)PyArray_DATA(weights_array);
    r = (const double*)PyArray_DATA(returns_array);

    /* return = x^T * r */
    for (i = 0; i < n; i++) {
        total_return += w[i] * r[i];
    }

    Py_DECREF(weights_array);
    Py_DECREF(returns_array);

    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  // Initialize NumPy C API
    return PyModule_Create(&moduledef);
}

